                var x = document.createElement('span');
                x.className = 'x';
                x.title = 'Remove';
                x.textContent = '\\u00d7';
                x.addEventListener('click', function (ev) { ev.stopPropagation(); chips.splice(i, 1); saveChips(); });
                b.appendChild(x);
