    if (gs < 8) { return; }
    var ox = ((view.x % gs) + gs) % gs, oy = ((view.y % gs) + gs) % gs;
    for (var x = ox; x < w; x += gs) { el('line', { 'class': 'grid-line', x1: x, y1: 0, x2: x, y2: h }, gridG); }
